const svg = (id, title, desc, inside, height = 300) => `<svg id="${id}" viewBox="0 0 760 ${height}" role="img" aria-labelledby="${id}-title ${id}-desc"><title id="${id}-title">${title}</title><desc id="${id}-desc">${desc}</desc>${inside}</svg>`;
const path = (d, color, width=3, extra='') => `<path d="${d}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round" ${extra}/>`;
const txt = (x,y,text,extra='') => `<text x="${x}" y="${y}" ${extra}>${text}</text>`;
const ln = (x1,y1,x2,y2,color='#8c9ba8',extra='') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" ${extra}/>`;
const arrow = (x1,y1,x2,y2,color='#187b8c') => {
  const a=Math.atan2(y2-y1,x2-x1), s=8;
  return `${ln(x1,y1,x2,y2,color,'stroke-width="2"')}${path(`M${x2-s*Math.cos(a-.45)},${y2-s*Math.sin(a-.45)}L${x2},${y2}L${x2-s*Math.cos(a+.45)},${y2-s*Math.sin(a+.45)}`,color,2)}`;
};
const num=(n,d=2)=>n.toLocaleString('nb-NO',{maximumFractionDigits:d});
const wavePath=(x0,x1,fn,step=2)=>{let d='';for(let x=x0;x<=x1;x+=step)d+=`${x===x0?'M':'L'}${x.toFixed(1)},${fn(x).toFixed(2)}`;return d;};
const style=`<style>
.wv-scope svg{display:block;width:100%;height:auto;overflow:hidden;background:var(--model-bg,#f1f6f7);border-radius:14px}.wv-scope svg text{font:14px system-ui,sans-serif;fill:var(--ink,#273d4a)}.wv-scope svg .wv-small{font-size:12px;fill:#657985}.wv-scope .wv-live{font-variant-numeric:tabular-nums}.wv-scope .wv-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.wv-scope .wv-buttons{display:flex;gap:8px;flex-wrap:wrap}.wv-scope .wv-buttons button{padding:8px 12px;border:1px solid #bcced2;border-radius:8px;background:var(--surface,#fff);color:var(--ink,#273d4a);cursor:pointer;font:inherit}.wv-scope .wv-buttons button[aria-pressed="true"]{background:#187b8c;color:#fff;border-color:#187b8c}.wv-scope select{max-width:100%;font:inherit}.wv-scope .controls{margin-top:14px}.wv-scope label{display:block}.wv-scope input[type="range"]{width:100%;accent-color:#187b8c}.wv-scope .wv-keyline{margin:12px 0 0;font-size:.92em}.wv-scope .wv-swatch{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:5px}.wv-scope .wv-legend{display:flex;gap:18px;flex-wrap:wrap;font-size:.88em;margin-top:9px}.wv-scope .wv-summary{padding:10px 12px;border-radius:9px;background:var(--surface,#fff);margin-top:12px}.wv-scope .wv-control-head{display:flex;justify-content:space-between;gap:10px}.wv-scope .wv-control-head output{font-weight:650;white-space:nowrap}@media(max-width:560px){.wv-scope .wv-grid{grid-template-columns:1fr}.wv-scope svg text{font-size:16px}.wv-scope svg .wv-small{font-size:14px}}
</style>`;
const box=(content)=>`<div class="wv-scope">${content}</div>`;
const range=(id,label,min,max,value,step='1')=>`<label class="control" for="${id}"><span class="wv-control-head"><span>${label}</span><output id="${id}-value"></output></span><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}"></label>`;
const select=(id,label,options)=>`<label class="control" for="${id}">${label}<select id="${id}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
const colors={wave:'#16879b',amber:'#d28a16',red:'#d75a55',purple:'#8260b4',green:'#398463'};

const basics = {
  id:'bolger',title:'Bølger og svingninger',kicker:'Fra svingning til bølge',
  summary:'Hva er det som flytter seg når en bølge brer seg? Utforsk amplitude, bølgelengde, frekvens og bølgefart.',
  sections:[
    {title:'En bølge frakter energi',body:`${style}<p>En <strong>svingning</strong> gjentas rundt en likevektsstilling. En <strong>bølge</strong> er svingninger som brer seg og overfører energi. I en mekanisk bølge svinger partiklene lokalt; de følger ikke bølgen hele veien.</p><div class="concept-grid"><div class="concept"><strong>Amplitude A</strong><p>Største avstand fra likevektsstillingen.</p></div><div class="concept"><strong>Bølgelengde λ</strong><p>Avstand mellom to nabotopper, eller to andre punkter i samme svingefase.</p></div><div class="concept"><strong>Frekvens f og periode T</strong><p>Antall svingninger per sekund (Hz), og tid per svingning (s).</p></div></div><p class="key">v = f · λ &nbsp; &nbsp; f = 1 / T</p>${box(`<div class="model">${svg('wv-travel','En løpende tversbølge','En turkis bølge brer seg mot høyre. Den oransje prikken svinger opp og ned på et fast sted. Glidere endrer amplitude, frekvens og bølgefart.','')}<div class="controls wv-grid">${range('wv-amplitude','Amplitude A',.2,1.2,.6,.1)}${range('wv-frequency','Frekvens f',.5,3,1,.1)}${range('wv-speed','Bølgefart v',2,8,4,.2)}</div><div id="wv-travel-readout" class="readout wv-live" aria-live="polite"></div><p class="model-note">Enkel modell av en bølge langs en streng. Stor amplitude betyr mer energi for samme streng og frekvens. Høyere frekvens alene sier ikke hvor mye total energi bølgen frakter.</p></div>`)}`},
    {title:'På tvers eller på langs?',body:`<p>I en <strong>tversbølge</strong> svinger partiklene vinkelrett på bølgens retning. I en <strong>langsbølge</strong> svinger de parallelt med retningen, slik luftpartikler gjør i lyd. Følg den oransje partikkelen.</p>${box(`<div class="model"><div class="wv-buttons" role="group" aria-label="Velg bølgetype"><button type="button" id="wv-transverse" aria-pressed="true">Tversbølge</button><button type="button" id="wv-longitudinal" aria-pressed="false">Langsbølge</button></div>${svg('wv-particles','Partikkelbevegelse i en mekanisk bølge','Velg tversbølge eller langsbølge. Partiklene svinger rundt faste steder, mens bølgemønsteret brer seg mot høyre.','',240)}<p id="wv-particles-caption" class="model-note">Partiklene svinger opp og ned. Bølgen brer seg mot høyre.</p></div>`)}<div class="concept-grid"><div class="concept"><strong>Mekaniske bølger</strong><p>Trenger et stoff å bre seg i: lyd i luft, bølger på en streng eller i vann. Overflatepartikler i vann beveger seg mer sammensatt enn en ren tversbølge.</p></div><div class="concept"><strong>Elektromagnetiske bølger</strong><p>Svingninger i elektriske og magnetiske felt. Kan bre seg gjennom vakuum, for eksempel sollys og radiosignaler.</p></div></div>`},
    {title:'Stående bølger: mønsteret blir på stedet',body:`<p>Når to like bølger går hver sin vei, kan de danne en <strong>stående bølge</strong>. <strong>Knuter</strong> er steder uten utslag. Mellom dem er <strong>buker</strong>, der utslaget er størst. Faste ender må være knuter.</p>${box(`<div class="model">${svg('wv-standing','Stående bølger på en streng','To bølger i motsatt retning danner et stående mønster. Velg hvor mange buker strengen har.','',260)}<div class="controls">${range('wv-harmonic','Antall buker',1,4,2,1)}</div><div id="wv-standing-readout" class="readout wv-live" aria-live="polite"></div><p class="model-note">Ideell streng med lengde 2 m og bølgefart 2 m/s. Bare svingemønstre som passer mellom de faste endene, kan bli stående.</p></div>`)}<p class="key">Prøv med en fjær eller et tau: Endre rytmen og se hvilke stående mønstre du klarer å lage.</p>`}
  ],
  terms:[{term:'Amplitude',definition:'Største utslag fra likevektsstillingen.'},{term:'Bølgelengde',definition:'Avstanden mellom to nabopunkter i samme svingefase.'},{term:'Frekvens',definition:'Antall svingninger per sekund, målt i hertz (Hz).'},{term:'Periode',definition:'Tiden for én hel svingning.'},{term:'Bølgefart',definition:'Farten bølgemønsteret brer seg med.'},{term:'Knute',definition:'Punkt uten utslag i en stående bølge.'},{term:'Buk',definition:'Sted med størst utslag i en stående bølge.'}],
  questions:[
    {id:'wv-b1',type:'mcq',level:'Start',prompt:'En lydbølge går gjennom luft. Hva gjør luftpartiklene?',choices:['Følger lyden hele veien fra høyttaleren til øret.','Svinger fram og tilbake omkring sine egne likevektsstillinger.','Står helt stille mens energien passerer.'],correct:1,answer:'Luftpartiklene svinger lokalt. Det er trykkvariasjonen og energien som brer seg gjennom lufta.'},
    {id:'wv-b2',type:'open',level:'Start',prompt:'Tegn en bølge. Marker likevektslinje, bølgetopp, bølgebunn, amplitude og bølgelengde.',answer:'Amplitude måles fra likevektslinjen til en topp eller bunn. Bølgelengden måles mellom to nabotopper eller to nabobunner. Avstanden fra bunn til topp er 2A.'},
    {id:'wv-b3',type:'number',level:'Bruk',prompt:'En bølge har fart 5 m/s og bølgelengde 2 m. Finn frekvensen.',value:2.5,tolerance:.02,unit:'Hz',hint:'Bruk v = f · λ og isoler f.',answer:'f = v / λ = 5 m/s / 2 m = <strong>2,5 Hz</strong>.'},
    {id:'wv-b4',type:'number',level:'Bruk',prompt:'En bølge har frekvens 2,5 Hz. Hva er perioden?',value:.4,tolerance:.005,unit:'s',hint:'Perioden er tiden per svingning.',answer:'T = 1 / f = 1 / 2,5 Hz = <strong>0,40 s</strong>.'},
    {id:'wv-b5',type:'number',level:'Bruk',prompt:'En A-tone har frekvens 440 Hz. Lydfarten er 345 m/s. Finn bølgelengden.',value:345/440,tolerance:.01,unit:'m',answer:'λ = v / f = 345 / 440 m ≈ <strong>0,784 m</strong>.'},
    {id:'wv-b6',type:'number',level:'Bruk',prompt:'Du står på stranda. Bølgene går med fart 4 m/s, og to bølgetopper passerer deg hvert sekund. Hvor langt er det mellom nabotoppene?',value:2,tolerance:.02,unit:'m',answer:'f = 2 Hz. λ = v / f = 4 / 2 m = <strong>2 m</strong>.'},
    {id:'wv-b7',type:'mcq',level:'Start',prompt:'Hva kjennetegner en langsbølge?',choices:['Partiklene svinger vinkelrett på retningen bølgen brer seg.','Partiklene svinger parallelt med retningen bølgen brer seg.','Bølgelengden er alltid større enn én meter.'],correct:1,answer:'I en langsbølge svinger partiklene langs bølgeretningen. Lyd i luft er et eksempel.'},
    {id:'wv-b8',type:'open',level:'Bruk',prompt:'En film viser en eksplosjon langt ute i verdensrommet. Kan astronauten se den? Kan astronauten høre den gjennom vakuum? Forklar.',answer:'Lys er elektromagnetisk stråling og kan gå gjennom vakuum, så eksplosjonen kan sees. Lyd er en mekanisk bølge og trenger et stoff. Den kan derfor ikke høres gjennom vakuum.'},
    {id:'wv-b9',type:'number',level:'Bruk',prompt:'Det går 3,0 s fra du ser et lyn til du hører tordenen. Regn med lydfart 340 m/s og se bort fra lysets reisetid. Hvor langt unna er lynet?',value:1020,tolerance:10,unit:'m',answer:'s = v · t = 340 m/s · 3,0 s = <strong>1020 m</strong>, omtrent 1 km.'},
    {id:'wv-b10',type:'mcq',level:'Bruk',prompt:'Frekvensen dobles mens bølgefarten holdes uendret. Hva skjer med bølgelengden?',choices:['Den dobles.','Den halveres.','Den er uendret.'],correct:1,answer:'λ = v / f. Når frekvensen dobles ved samme bølgefart, halveres bølgelengden.'},
    {id:'wv-b11',type:'open',level:'Bruk',prompt:'Lag to stående bølger på en 2 m lang streng med faste ender: én med én buk og én med to buker. Finn bølgelengden i hvert tilfelle.',answer:'Én buk er en halv bølgelengde: λ = 2L = <strong>4 m</strong>. To buker er én hel bølgelengde: λ = L = <strong>2 m</strong>. Endene er knuter.'},
    {id:'wv-b12',type:'open',level:'Utfordring',prompt:'En elev sier: «Når vi sender mer energi inn i en fjær, må bølgelengden bli kortere.» Vurder påstanden.',answer:'Ikke nødvendigvis. Mer energi kan gi større amplitude. Bølgelengden bestemmes av bølgefart og frekvens gjennom λ = v/f. Holder vi disse uendret, er bølgelengden uendret.'}
  ],resources:[{label:'PhET: Bølge på en snor',url:'https://phet.colorado.edu/sims/html/wave-on-a-string/latest/wave-on-a-string_all.html'}],
  mount(root,api){
    const q=id=>root.querySelector('#'+id), get=id=>Number(q(id).value);
    let transverse=true;
    const update=()=>{q('wv-amplitude-value').textContent=num(get('wv-amplitude'))+' m';q('wv-frequency-value').textContent=num(get('wv-frequency'))+' Hz';q('wv-speed-value').textContent=num(get('wv-speed'))+' m/s';q('wv-travel-readout').textContent=`Bølgelengde λ = ${num(get('wv-speed')/get('wv-frequency'))} m · Periode T = ${num(1/get('wv-frequency'))} s`;q('wv-harmonic-value').textContent=get('wv-harmonic');let n=get('wv-harmonic');q('wv-standing-readout').textContent=`${n} ${n===1?'buk':'buker'} · ${n+1} knuter · λ = ${num(4/n)} m · f = ${num(n*.5)} Hz`;api.repaint();};
    ['wv-amplitude','wv-frequency','wv-speed','wv-harmonic'].forEach(id=>q(id).addEventListener('input',update));
    ['wv-transverse','wv-longitudinal'].forEach((id,i)=>q(id).addEventListener('click',()=>{transverse=i===0;q('wv-transverse').setAttribute('aria-pressed',transverse);q('wv-longitudinal').setAttribute('aria-pressed',!transverse);q('wv-particles-caption').textContent=transverse?'Partiklene svinger opp og ned. Bølgen brer seg mot høyre.':'Partiklene svinger fram og tilbake. Fortetninger og fortynninger brer seg mot høyre.';api.repaint();}));
    const waveLayer=document.createElementNS('http://www.w3.org/2000/svg','g');q('wv-travel').append(waveLayer);
    const particleLayer=document.createElementNS('http://www.w3.org/2000/svg','g');q('wv-particles').append(particleLayer);
    const standingLayer=document.createElementNS('http://www.w3.org/2000/svg','g');q('wv-standing').append(standingLayer);
    api.onFrame(t=>{
      const A=get('wv-amplitude'),f=get('wv-frequency'),v=get('wv-speed'),lambda=v/f;
      const y=x=>158-A*52*Math.sin(2*Math.PI*((x-50)/(40*lambda)-f*t));
      let grid='';for(let x=50;x<=710;x+=40)grid+=ln(x,82,x,232,'#dbe5e8')+(x===50||((x-50)/40)%4===0?txt(x,254,num((x-50)/40),'text-anchor="middle" class="wv-small"'):'');
      waveLayer.innerHTML=`${grid}${ln(50,158,710,158,'#9fb2bb')}${ln(50,82,50,232)}${path(wavePath(50,710,y),colors.wave,3.5)}${ln(330,83,330,232,colors.amber,'stroke-dasharray="3 5" opacity=".5"')}<circle cx="330" cy="${y(330)}" r="7" fill="${colors.amber}" stroke="white" stroke-width="2"/>${ln(30,158-A*52,30,158,colors.amber,'stroke-width="2"')}${txt(24,155-A*26,'A','text-anchor="end"')}${arrow(50,52,50+lambda*40,52,colors.purple)}${txt(50+lambda*20,37,'λ','text-anchor="middle"')}${arrow(595,273,698,273)}${txt(587,277,'Bølgeretning','text-anchor="end" class="wv-small"')}${txt(710,254,'x (m)','text-anchor="end" class="wv-small"')}${txt(63,100,'Likevektslinje','class="wv-small"')}`;
      let particles='';for(let i=0;i<16;i++){const x0=80+i*40,phase=2*Math.PI*(i/7-.65*t), x=transverse?x0:x0+17*Math.sin(phase),y=transverse?135-38*Math.sin(phase):135;particles+=`<circle cx="${x0}" cy="135" r="3" fill="#b3c5cc"/>${i===7?ln(x0,transverse?80:135,transverse?x0:x0+23,transverse?190:135,colors.amber,'stroke-dasharray="3 4"'):''}<circle cx="${x}" cy="${y}" r="${i===7?9:6}" fill="${i===7?colors.amber:colors.wave}"/>`;}
      particleLayer.innerHTML=`${arrow(260,45,500,45)}${txt(380,30,'Bølgeretning','text-anchor="middle"')}${particles}${txt(380,216,'Den oransje partikkelen blir i nærheten av samme sted.','text-anchor="middle" class="wv-small"')}`;
      const n=get('wv-harmonic'),stY=x=>140-52*Math.sin(n*Math.PI*(x-50)/660)*Math.cos(2*Math.PI*n*.5*t);
      let nodes='';for(let k=0;k<=n;k++)nodes+=`<circle cx="${50+k*660/n}" cy="140" r="5" fill="${colors.purple}"/>`;let envelopes='';for(const sign of [-1,1])envelopes+=path(wavePath(50,710,x=>140+sign*52*Math.sin(n*Math.PI*(x-50)/660)),'#c2d8dc',1.5,'stroke-dasharray="4 5"');
      standingLayer.innerHTML=`${txt(50,35,'Faste ender','class="wv-small"')}${ln(50,140,710,140,'#b2c4cc')}${ln(44,70,44,210,'#7c929e','stroke-width="6"')}${ln(716,70,716,210,'#7c929e','stroke-width="6"')}${envelopes}${path(wavePath(50,710,stY),colors.wave,4)}${nodes}${ln(50,233,710,233,'#9fb2bb')}${txt(380,253,'Strenglengde L = 2 m','text-anchor="middle" class="wv-small"')}${txt(600,35,'● knute','fill="#8260b4"')}`;
    });update();
  }
};

const phenomena={
  id:'fenomener',title:'Bølgefenomener',kicker:'Sju måter bølger oppfører seg',summary:'Refleksjon, absorpsjon, brytning, interferens, bøyning, resonans og dopplereffekt. Se hva som skjer, og prøv selv.',
  sections:[
    {title:'Refleksjon: bølgen sendes tilbake',body:`${style}<p>Når en bølge treffer en flate og sendes tilbake, får vi <strong>refleksjon</strong>. Vinklene måles fra <strong>innfallsloddet</strong>, som står vinkelrett på flaten. For speilende refleksjon er innfallsvinkelen lik refleksjonsvinkelen.</p>${box(`<div class="model">${svg('wv-reflection','Refleksjon fra et plant speil','Innkommende og reflektert lys danner like store vinkler med innfallsloddet. Endre innfallsvinkelen.','')}<div class="controls">${range('wv-angle','Innfallsvinkel',5,80,40,1)}</div><div id="wv-reflection-readout" class="readout wv-live" aria-live="polite"></div><p class="model-note">Eksempler: et speil, ekko og ekkolodd. Figuren viser en glatt flate; ru flater sender lys tilbake i mange retninger.</p></div>`)}`},
    {title:'Absorpsjon: energien tas opp',body:`<p>Lys som <strong>absorberes</strong>, avgir energi til stoffet, ofte som varme. Andre deler kan reflekteres eller slippe gjennom. En rød flate i hvitt lys reflekterer mye rødt og absorberer mer av de andre fargene.</p>${box(`<div class="model">${svg('wv-absorption','Hva reflekteres og hva absorberes?','Velg lysets farge og en ugjennomsiktig overflate. RGB-komponentene som flaten reflekterer vises, mens resten absorberes.','',260)}<div class="controls wv-grid">${select('wv-light','Belysning',[['white','Hvitt lys'],['red','Rødt lys'],['green','Grønt lys'],['blue','Blått lys']])}${select('wv-surface','Overflate',[['red','Rød'],['green','Grønn'],['blue','Blå'],['white','Hvit'],['black','Svart']])}</div><div id="wv-absorption-readout" class="readout" aria-live="polite"></div><p class="model-note">Forenklet RGB-modell av helt ugjennomsiktige flater: ingen transmisjon. Virkelige flater reflekterer og absorberer bredere bølgelengdeområder.</p></div>`)}`},
    {title:'Brytning: ny fart gir ny retning',body:`<p>En bølge kan endre retning når farten endres i overgangen mellom to medier. Lyset bøyes <strong>mot innfallsloddet</strong> når det går saktere. <strong>Frekvensen er uendret</strong>, så lavere fart gir kortere bølgelengde. Ved rett innfall endres farten uten at retningen endres.</p>${box(`<div class="model">${svg('wv-refraction','Lysbrytning mellom to medier','Endre innfallsvinkel og medier. Stråleretningen følger brytningsloven. Fra glass til luft kan du få totalrefleksjon.','')}<div class="controls wv-grid">${range('wv-refract-angle','Innfallsvinkel',0,80,45,1)}${select('wv-media','Fra → til',[['water','Luft → vann'],['glass','Luft → glass'],['out','Glass → luft']])}</div><div id="wv-refraction-readout" class="readout wv-live" aria-live="polite"></div><p class="model-note">Beregnet med brytningsloven. Stråletykkelsen viser retning, ikke energifordeling. Regnbuer skyldes brytning som avhenger av farge, sammen med refleksjon inne i dråpene.</p></div>`)}`},
    {title:'Interferens: utslagene legges sammen',body:`<p>Bølger kan være på samme sted samtidig. Det samlede utslaget er <strong>summen</strong>. To like bølger i fase gir forsterkning. Like store bølger i motfase kan gi full utslokking på stedet de møtes.</p>${box(`<div class="model">${svg('wv-interference','To bølger og summen av dem','Turkis og lilla bølge har samme frekvens og amplitude. Den oransje sumkurven endres når du justerer faseforskjellen.','',350)}<div class="controls">${range('wv-phase','Faseforskjell',0,360,60,5)}</div><div id="wv-interference-readout" class="readout wv-live" aria-live="polite"></div><p class="model-note">Begge bølgene har amplitude A. 0°: i fase. 180°: motfase. Støydempende hodetelefoner lager omtrent motsatt lyd ved øret, slik at lyden der dempes.</p></div>`)}`},
    {title:'Bøyning: bølger sprer seg bak en åpning',body:`<p>Bølger kan bre seg inn bak kanter eller gjennom åpninger. <strong>Bøyning</strong> blir særlig tydelig når åpningen ikke er mye større enn bølgelengden. Derfor bøyes lyd merkbart rundt en dør, mens synlig lys nesten går rett fram på den skalaen.</p>${box(`<div class="model">${svg('wv-diffraction','Bølger gjennom en spalte','Endre spaltebredden og bølgelengden. Etter en smal åpning sprer bølgefrontene seg mer til sidene.','')}<div class="controls wv-grid">${range('wv-slit','Åpningens bredde a',.5,4,1,.1)}${range('wv-diff-lambda','Bølgelengde λ',.3,1.2,.8,.1)}</div><div id="wv-diffraction-readout" class="readout wv-live" aria-live="polite"></div><p class="model-note">Skjematisk visning: sirkelfronter viser spredningen, og lysstyrken viser en idealisert spaltefordeling langt fra åpningen. Den beskriver ikke detaljene i bølgefeltet rett ved spalten.</p></div>`)}`},
    {title:'Resonans: riktig rytme gir store svingninger',body:`<p>Et system har en naturlig svingefrekvens, <strong>egenfrekvensen</strong>. En gjentatt påvirkning nær denne frekvensen kan gi stor amplitude: <strong>resonans</strong>. Demping begrenser hvor stor amplituden blir. Tenk på en huske som dyttes i riktig rytme.</p>${box(`<div class="model">${svg('wv-resonance','Responsen til et drevet svingesystem','Kurven viser hvor stor amplituden er ved ulike frekvenser. En fjær med en masse svinger med amplituden som passer til valgt frekvens.','')}<div class="controls">${range('wv-drive','Påvirkningens frekvens',.3,1.7,.6,.02)}</div><div id="wv-resonance-readout" class="readout wv-live" aria-live="polite"></div><p class="model-note">Lineær fjærmodell med egenfrekvens 1 Hz og moderat demping. Kurven viser responsen etter at svingningen har stabilisert seg, ikke oppbyggingen fra ro.</p></div>`)}`},
    {title:'Dopplereffekt: bevegelse endrer mottatt frekvens',body:`<p>Når kilden nærmer seg, kommer bølgetoppene tettere: mottakeren får <strong>høyere frekvens</strong>. Når kilden fjerner seg, blir frekvensen lavere. For lys tilsvarer dette blåforskyvning og rødforskyvning.</p>${box(`<div class="model">${svg('wv-doppler','Dopplereffekt fra en bevegelig lydkilde','En kilde sender ut bølgefronter mens den beveger seg. Bølgene er tettere foran kilden enn bak. To mottakere står stille.','',320)}<div class="controls">${range('wv-source-speed','Kildefart som andel av lydfarten',-.6,.6,.35,.05)}</div><div id="wv-doppler-readout" class="readout wv-live" aria-live="polite"></div><p class="model-note">Modell for lyd med stillestående luft og mottakere. Kildens egen frekvens er 500 Hz; visningen er kraftig nedskalert i tid og rom. Lys krever en annen formel. Sekvensen starter på nytt med jevne mellomrom.</p></div>`)}`}
  ],
  terms:[{term:'Refleksjon',definition:'En bølge sendes tilbake fra en flate.'},{term:'Absorpsjon',definition:'Bølgeenergi tas opp i stoffet.'},{term:'Brytning',definition:'Retningsendring når en bølge får ny fart i et annet medium.'},{term:'Interferens',definition:'Bølger overlapper, og utslagene legges sammen.'},{term:'Bøyning',definition:'Bølger sprer seg bak åpninger og kanter.'},{term:'Resonans',definition:'Stor svingeamplitude ved gjentatt påvirkning nær egenfrekvensen.'},{term:'Dopplereffekt',definition:'Mottatt frekvens endres ved relativ bevegelse mellom bølgekilde og mottaker.'},{term:'Innfallslodd',definition:'Linje vinkelrett på flaten i treffpunktet.'}],
  questions:[
    {id:'wv-f1',type:'number',level:'Start',prompt:'En lysstråle treffer et plant speil med innfallsvinkel 35°. Hvor stor er refleksjonsvinkelen, målt fra innfallsloddet?',value:35,tolerance:.1,unit:'°',answer:'Refleksjonsvinkel = innfallsvinkel = <strong>35°</strong>.'},
    {id:'wv-f2',type:'open',level:'Bruk',prompt:'Tegn et plant speil, innfallslodd og en innkommende stråle som lager 30° med selve speilflaten. Tegn den reflekterte strålen, og finn innfallsvinkelen.',answer:'Innfallsloddet står 90° på speilet. Innfallsvinkelen er 90° − 30° = <strong>60°</strong>. Refleksjonsvinkelen er også 60°, på motsatt side av innfallsloddet.'},
    {id:'wv-f3',type:'mcq',level:'Start',prompt:'En ideelt rød, ugjennomsiktig flate belyses bare med blått lys. Hvordan ser den ut i den enkle fargemodellen?',choices:['Rød og lys.','Blå og lys.','Mørk, fordi det blå lyset absorberes.'],correct:2,answer:'Det finnes ikke rødt lys å reflektere. Den ideelle røde flaten absorberer det blå lyset og ser mørk ut. Virkelige overflater er mindre ideelle.'},
    {id:'wv-f4',type:'mcq',level:'Bruk',prompt:'Lys går fra luft til glass og får lavere fart. Hva skjer med frekvens og bølgelengde?',choices:['Begge minker.','Frekvensen er uendret, og bølgelengden blir kortere.','Frekvensen øker, og bølgelengden er uendret.'],correct:1,answer:'Frekvensen bestemmes av kilden og er uendret ved overgangen. Siden λ = v/f, gir lavere fart kortere bølgelengde.'},
    {id:'wv-f5',type:'open',level:'Bruk',prompt:'En blyant står halvveis ned i et glass vann og ser knekt ut sett på skrå. Forklar uten å si at selve blyanten bøyer seg.',answer:'Lys fra den nedsenkede delen endrer fart og retning i overgangen mellom vann og luft. Øyet tolker lyset som om det hadde gått rett fram, slik at den delen ser forskjøvet ut.'},
    {id:'wv-f6',type:'number',level:'Bruk',prompt:'To like bølger med amplitude 3 cm møtes nøyaktig i fase. Hva er amplituden til summen?',value:6,tolerance:.05,unit:'cm',answer:'Utslagene legges sammen: A<sub>sum</sub> = 3 cm + 3 cm = <strong>6 cm</strong>.'},
    {id:'wv-f7',type:'open',level:'Bruk',prompt:'Hvordan kan en hodetelefon dempe støy ved å sende ut mer lyd?',answer:'En mikrofon registrerer støy, og hodetelefonen sender ut lyd med omtrent motsatt utslag ved øret. Destruktiv interferens reduserer det samlede lydtrykket der. Dempingen er ikke like god for alle frekvenser og alle steder.'},
    {id:'wv-f8',type:'mcq',level:'Bruk',prompt:'Bølgelengden holdes uendret. Hva gir tydeligst bøyning gjennom en åpning?',choices:['En åpning som er mange tusen bølgelengder bred.','En åpning på omtrent én bølgelengde.','Åpningens bredde har ingen betydning.'],correct:1,answer:'Bøyning blir særlig tydelig når åpningens bredde er sammenlignbar med bølgelengden eller mindre.'},
    {id:'wv-f9',type:'open',level:'Bruk',prompt:'Du hører noen snakke ute i gangen selv om du ikke kan se personen gjennom døra. Hvorfor er ikke bøyningen like tydelig for synlig lys?',answer:'Lyd har bølgelengder fra centimeter til meter og bøyes derfor merkbart i en døråpning. Synlig lys har bølgelengder på under en tusendels millimeter. Døra er enorm sammenlignet med lysbølgelengden, så bøyningen er svært liten på denne skalaen.'},
    {id:'wv-f10',type:'mcq',level:'Start',prompt:'Når får en huske vanligvis størst utslag av like store, gjentatte dytt?',choices:['Når dyttene følger omtrent huskas egen svingerytme.','Når dyttene kommer så fort som mulig.','Når dyttene alltid kommer på tilfeldige tidspunkt.'],correct:0,answer:'Dyttes huska i riktig rytme og retning, overføres energi effektivt. Dette er resonans. Demping gjør at utslaget ikke vokser uten grense.'},
    {id:'wv-f11',type:'open',level:'Bruk',prompt:'To stemmegafler står nær hverandre. Den ene kan begynne å svinge når du slår på den andre. Hvorfor virker dette best når de har samme egenfrekvens?',answer:'Lydbølgene fra den første påvirker den andre periodisk. Når frekvensen passer med egenfrekvensen, kan den andre ta opp energi effektivt og få merkbar amplitude: resonans.'},
    {id:'wv-f12',type:'mcq',level:'Start',prompt:'En ambulanse kjører mot deg med konstant sirenefrekvens. Hvordan er frekvensen du hører sammenlignet med sirenens egen frekvens?',choices:['Lavere.','Den samme.','Høyere.'],correct:2,answer:'Kilden flytter seg nærmere mellom hver utsendte bølgetopp. Avstanden mellom toppene foran ambulansen blir mindre, så mottatt frekvens øker.'},
    {id:'wv-f13',type:'open',level:'Bruk',prompt:'Absorpsjonslinjene i lyset fra en stjerne er flyttet mot lengre bølgelengder sammenlignet med samme grunnstoff målt i laboratoriet. Hva kaller vi dette, og hva kan det fortelle om bevegelsen?',answer:'Det er <strong>rødforskyvning</strong>. For en stjerne kan det skyldes at stjernen beveger seg fra oss langs synslinjen. For fjerne galakser må universets utvidelse også tas med i forklaringen.'},
    {id:'wv-f14',type:'open',level:'Utfordring',prompt:'Hvor høyt må et plant speil minst være for at du skal kunne se hele kroppen, fra føtter til toppen av hodet? Anta at speilet plasseres riktig og at øynene er punktformede.',answer:'Speilet må være <strong>halvparten av kroppshøyden</strong>. Lyset fra føttene treffer speilet halvveis mellom føttene og øyehøyden; lyset fra toppen treffer halvveis mellom hodetoppen og øyehøyden. Avstanden mellom disse treffpunktene er halve kroppshøyden. Dette er uavhengig av hvor langt fra speilet du står.'}
  ],resources:[{label:'PhET: Brytning av lys',url:'https://phet.colorado.edu/sims/html/bending-light/latest/bending-light_all.html'},{label:'PhET: Bølgeinterferens',url:'https://phet.colorado.edu/sims/html/wave-interference/latest/wave-interference_all.html'}],
  mount(root,api){
    const q=id=>root.querySelector('#'+id), get=id=>Number(q(id).value), layers={};
    const say=(id,message)=>{const el=q(id);if(el.textContent!==message)el.textContent=message;};
    ['reflection','absorption','refraction','interference','diffraction','resonance','doppler'].forEach(id=>{const g=document.createElementNS('http://www.w3.org/2000/svg','g');q('wv-'+id).append(g);layers[id]=g;});
    const update=()=>{for(const id of ['wv-angle','wv-refract-angle'])q(id+'-value').textContent=num(get(id),0)+'°';q('wv-phase-value').textContent=num(get('wv-phase'),0)+'°';for(const id of ['wv-slit','wv-diff-lambda'])q(id+'-value').textContent=num(get(id))+' m';q('wv-drive-value').textContent=num(get('wv-drive'))+' Hz';const ratio=get('wv-source-speed');q('wv-source-speed-value').textContent=num(Math.abs(ratio)*100,0)+' % '+(ratio>0?'mot høyre':ratio<0?'mot venstre':'(i ro)');q('wv-reflection-readout').textContent=`Innfallsvinkel = refleksjonsvinkel = ${get('wv-angle')}°`;let a=get('wv-phase')*Math.PI/180,amp=2*Math.abs(Math.cos(a/2));q('wv-interference-readout').textContent=`Summens amplitude = ${num(amp)} · A. ${amp<.01?'Full utslokking i denne ideelle modellen.':amp>1.99?'Full forsterkning.':'Delvis forsterkning eller utslokking.'}`;let r=get('wv-slit')/get('wv-diff-lambda');q('wv-diffraction-readout').textContent=`a / λ = ${num(r)}. ${r<1.5?'Bred spredning bak åpningen.':'Bredere åpning i forhold til bølgelengden gir smalere hovedretning.'}`;const f=get('wv-drive');q('wv-resonance-readout').textContent=`Egenfrekvens: 1 Hz · Påvirkning: ${num(f)} Hz · ${Math.abs(f-1)<.15?'Nær resonans: stor amplitude.':'Prøv en frekvens nær 1 Hz.'}`;q('wv-doppler-readout').textContent=`Venstre mottaker: ${num(500/(1+ratio),0)} Hz · Kilde: 500 Hz · Høyre mottaker: ${num(500/(1-ratio),0)} Hz`;api.repaint();};
    root.querySelectorAll('.wv-scope input,.wv-scope select').forEach(el=>el.addEventListener('input',update));
    api.onFrame(t=>{
      // Reflection. All angles are measured from the normal.
      let angle=get('wv-angle'),a=angle*Math.PI/180,rad=180,x=380,yy=224;
      const ix=x-rad*Math.sin(a),iy=yy-rad*Math.cos(a),ox=x+rad*Math.sin(a),oy=iy;
      const angleLabelOffset=Math.max(27,83*Math.sin(a/2));
      layers.reflection.innerHTML=`<rect x="50" y="224" width="660" height="16" rx="4" fill="#a5b8c1"/>${ln(x,32,x,224,'#9fb0ba','stroke-dasharray="6 5"')}${txt(x+10,32,'Innfallslodd','class="wv-small"')}${arrow(ix,iy,x,yy,colors.amber)}${arrow(x,yy,ox,oy,colors.wave)}${txt(Math.min(680,ox+10),Math.max(64,oy),'Reflektert','class="wv-small"')}${txt(Math.max(50,ix-10),Math.max(64,iy),'Innkommende','text-anchor="end" class="wv-small"')}${path(`M380,172 A52,52 0 0 0 ${380-52*Math.sin(a)},${224-52*Math.cos(a)}`,colors.amber,2)}${path(`M380,172 A52,52 0 0 1 ${380+52*Math.sin(a)},${224-52*Math.cos(a)}`,colors.wave,2)}${txt(380-angleLabelOffset,224-83*Math.cos(a/2),angle+'°','text-anchor="middle"')}${txt(380+angleLabelOffset,224-83*Math.cos(a/2),angle+'°','text-anchor="middle"')}${txt(380,279,'Speilende flate','text-anchor="middle" class="wv-small"')}`;
      // Ideal opaque RGB surface, no arbitrary energy fractions.
      const light=q('wv-light').value,surface=q('wv-surface').value, keys=['red','green','blue'],cols=['#d75a55','#398463','#4e7fcd'],names={red:'rødt',green:'grønt',blue:'blått'};
      const incident=light==='white'?keys:[light],reflect=incident.filter(c=>surface==='white'||surface===c),absorb=incident.filter(c=>!reflect.includes(c));
      const surfaceColor={red:cols[0],green:cols[1],blue:cols[2],white:'#fff',black:'#29353a'}[surface];
      let rays='';keys.forEach((c,i)=>{const y=93+i*23;if(incident.includes(c)){rays+=arrow(90,y,366,y,cols[i]);if(reflect.includes(c))rays+=arrow(392,y,635,48+i*18,cols[i]);else rays+=arrow(390,y,465,y,cols[i])+'<circle cx="465" cy="'+y+'" r="5" fill="'+cols[i]+'"/>';}});
      layers.absorption.innerHTML=`${txt(90,47,'Innkommende lys')}${txt(622,27,'Reflektert lys','text-anchor="middle"') }<rect x="376" y="72" width="190" height="137" rx="14" fill="${surfaceColor}" stroke="#9cb0ba" stroke-width="2"/>${rays}${txt(471,235,'Ugjennomsiktig flate','text-anchor="middle" class="wv-small"')}`;
      say('wv-absorption-readout',`Reflektert: ${reflect.length?reflect.map(c=>names[c]).join(', '):'ingen av de valgte lysfargene'}. Absorbert: ${absorb.length?absorb.map(c=>names[c]).join(', '):'ingen i denne idealmodellen'}.`);
      // Snell's law, including total internal reflection.
      const mode=q('wv-media').value,n1=mode==='out'?1.5:1,n2=mode==='water'?1.33:mode==='glass'?1.5:1,namesMedia=mode==='out'?['Glass','Luft']:mode==='water'?['Luft','Vann']:['Luft','Glass'];
      a=get('wv-refract-angle')*Math.PI/180;let s=n1/n2*Math.sin(a),tir=s>1,theta=tir?null:Math.asin(s);x=380;yy=145;
      let refracted=tir?'':arrow(x,yy,x+140*Math.sin(theta),yy+140*Math.cos(theta),colors.wave);
      layers.refraction.innerHTML=`<rect x="20" y="145" width="720" height="155" fill="${mode==='out'?'#edf3f5':'#dcecf0'}"/>${ln(20,145,740,145,'#8ba8b5')}${ln(380,16,380,285,'#9fb0ba','stroke-dasharray="5 5"')}${txt(40,38,namesMedia[0]+' · n = '+num(n1))}${txt(40,180,namesMedia[1]+' · n = '+num(n2))}${arrow(380-128*Math.sin(a),145-128*Math.cos(a),380,145,colors.amber)}${arrow(380,145,380+128*Math.sin(a),145-128*Math.cos(a),tir?colors.wave:'#a9bdc5')}${refracted}${txt(397,34,'Innfallslodd','class="wv-small"')}${tir?txt(500,240,'Totalrefleksjon','text-anchor="middle"'):txt(560,274,'Brutt stråle','class="wv-small"')}`;
      say('wv-refraction-readout',tir?`Totalrefleksjon: ingen lysstråle går videre ut. Grensevinkelen er ${num(Math.asin(n2/n1)*180/Math.PI,1)}°.`:`Brytningsvinkel: ${num(theta*180/Math.PI,1)}° · Farten blir ${num(n1/n2)} ganger så stor · Bølgelengden blir ${num(n1/n2)} ganger så stor · Frekvensen er uendret.`);
      // Interference of two equal sinusoidal waves.
      const phase=get('wv-phase')*Math.PI/180;let curves='';const fn=(px,p)=>Math.sin(2*Math.PI*((px-90)/220-.45*t)+p);
      [[76,colors.wave,0,'Bølge 1'],[164,colors.purple,phase,'Bølge 2']].forEach(([base,c,p,label])=>{curves+=ln(95,base,715,base,'#c2d0d7')+txt(21,base+4,label,'class="wv-small"')+path(wavePath(95,715,z=>base-25*fn(z,p)),c,3);});
      curves+=ln(95,275,715,275,'#c2d0d7')+txt(21,279,'Sum','class="wv-small"')+path(wavePath(95,715,z=>275-25*(fn(z,0)+fn(z,phase))),colors.amber,3.5);
      layers.interference.innerHTML=curves;
      // Angular sinc envelope for a single slit, displayed on circular fronts.
      const gap=get('wv-slit'),lam=get('wv-diff-lambda'),pxUnit=34,half=gap*pxUnit/2,k=2*Math.PI/(lam*pxUnit),vel=40,period=lam*pxUnit/vel;let field='';
      for(let j=0;j<20;j++){const xp=300-((t*vel+j*lam*pxUnit)%(300+lam*pxUnit));if(xp>25)field+=ln(xp,30,xp,270,colors.wave,'stroke-width="2" opacity=".55"');}
      for(let j=0;j<22;j++){const radius=((t%period)+j*period)*vel;if(radius<8||radius>530)continue;for(let theta=-Math.PI/2;theta<Math.PI/2;theta+=.055){const z=Math.PI*gap/lam*Math.sin(theta),intensity=Math.abs(z)<.001?1:(Math.sin(z)/z)**2;if(intensity<.015)continue;const th2=theta+.055,x1=300+radius*Math.cos(theta),y1=150+radius*Math.sin(theta),x2=300+radius*Math.cos(th2),y2=150+radius*Math.sin(th2);if(Math.max(y1,y2)<25||Math.min(y1,y2)>275||Math.min(x1,x2)>735)continue;field+=ln(x1,y1,x2,y2,colors.wave,`stroke-width="2.6" opacity="${(.13+.75*Math.sqrt(intensity)).toFixed(2)}"`);}}
      layers.diffraction.innerHTML=`<defs><clipPath id="wv-diff-clip"><rect x="24" y="25" width="712" height="250" rx="5"/></clipPath></defs><g clip-path="url(#wv-diff-clip)">${field}<rect x="294" y="25" width="12" height="${125-half}" fill="#7e949e"/><rect x="294" y="${150+half}" width="12" height="${125-half}" fill="#7e949e"/></g>${txt(39,18,'Flate bølgefronter','class="wv-small"')}${txt(440,18,'Spredning bak åpningen','class="wv-small"')}${txt(300,295,'Spalte','text-anchor="middle" class="wv-small"')}`;
      // Driven damped harmonic oscillator: steady-state amplitude and phase.
      const drive=get('wv-drive'),zeta=.16,amp=r=>1/Math.sqrt((1-r*r)**2+(2*zeta*r)**2),response=amp(drive),delta=Math.atan2(2*zeta*drive,1-drive*drive),disp=18*response*Math.cos(2*Math.PI*drive*t-delta),massX=550+disp;
      let spring=`M424,153`;for(let i=0;i<=14;i++){const sx=428+(massX-40-428)*i/14,sy=i===0||i===14?153:153+(i%2?12:-12);spring+=`L${sx},${sy}`;}
      let curve=wavePath(60,320,px=>238-47*amp((px-60)/260*1.8));let markX=60+drive/1.8*260,markY=238-47*response;
      layers.resonance.innerHTML=`${ln(60,238,332,238)}${ln(60,50,60,238)}${path(curve,colors.wave,3)}${ln(60+260/1.8,50,60+260/1.8,238,'#a7b7bf','stroke-dasharray="4 5"')}<circle cx="${markX}" cy="${markY}" r="6" fill="${colors.amber}"/>${txt(60,33,'Amplitude','class="wv-small"')}${txt(60+260/1.8,258,'1 Hz','text-anchor="middle" class="wv-small"')}${txt(320,280,'Påvirkningens frekvens','text-anchor="end" class="wv-small"')}${ln(420,83,420,224,'#849ba7','stroke-width="7"')}${path(spring,colors.purple,3)}<rect x="${massX-35}" y="123" width="70" height="60" rx="9" fill="${colors.wave}"/><circle cx="${massX-22}" cy="193" r="7" fill="#758d98"/><circle cx="${massX+22}" cy="193" r="7" fill="#758d98"/>${ln(430,203,710,203,'#9fb2bb')}${txt(550,75,'Masse på fjær','text-anchor="middle"')}${txt(550,255,'Større respons nær egenfrekvensen','text-anchor="middle" class="wv-small"')}`;
      // Expanding wavefronts emitted at the moving source's former positions.
      const ratio=get('wv-source-speed'),local=t%7,c=86,vs=ratio*c,initial=ratio>0?145:ratio<0?615:380,sourceX=initial+vs*local;let rings='';
      for(let e=0;e<=local;e+=.55){const radius=c*(local-e);rings+=`<circle cx="${initial+vs*e}" cy="165" r="${radius}" fill="none" stroke="${colors.wave}" stroke-width="2" opacity="${Math.max(.12,.8-radius/650)}"/>`;}
      layers.doppler.innerHTML=`<defs><clipPath id="wv-dop-clip"><rect x="24" y="45" width="712" height="250" rx="8"/></clipPath></defs><g clip-path="url(#wv-dop-clip)">${rings}</g><circle cx="${sourceX}" cy="165" r="12" fill="${colors.amber}" stroke="white" stroke-width="3"/>${ratio?arrow(sourceX-25*Math.sign(ratio),126,sourceX+25*Math.sign(ratio),126,colors.amber):''}<rect x="70" y="151" width="18" height="28" rx="5" fill="${colors.purple}"/><rect x="672" y="151" width="18" height="28" rx="5" fill="${colors.purple}"/>${txt(78,30,'Venstre mottaker','text-anchor="middle" class="wv-small"')}${txt(681,30,'Høyre mottaker','text-anchor="middle" class="wv-small"')}${txt(380,307,'Oransje: kilde · Turkis: utsendte bølgefronter','text-anchor="middle" class="wv-small"')}`;
    });update();
  }
};

